"""Meridian CRM RBAC permission check migration."""

from typing import Any


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether *user* may perform *action* on *object* and *record*.

    Permissions deny by default.  A matching role/object/action row is required,
    including for ADMIN users.  ADMIN bypasses scope restrictions only.
    """
    role_id = user.get("ROLE_ID", "")

    matching_scope: Any = None
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            matching_scope = row.get("scope", "")
            break

    if matching_scope is None:
        return False

    if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
        return False

    if role_id == "ADMIN":
        return True

    if matching_scope == "ALL":
        return True
    if matching_scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if matching_scope == "OWN":
        return record.get("OWNER_UID", "") == user.get("USR_ID", "")

    return False
